const fleet = $('Get vehicles').first().json;
const maintenance = $input.first().json;
if (!Array.isArray(fleet.vehicles) || (fleet.truncated !== undefined && typeof fleet.truncated !== 'boolean') || !Array.isArray(maintenance.open) || !Array.isArray(maintenance.recent)) {
  throw new Error('Unexpected Fleetkeep response; no summary was produced.');
}
return [{ json: {
  vehicleCountReturned: fleet.vehicles.length,
  completeVehicleList: typeof fleet.truncated === 'boolean' ? !fleet.truncated : null,
  warning: fleet.truncated === true ? 'Vehicle list is truncated. Review Fleetkeep before using fleet totals.' : fleet.truncated === false ? null : 'The API does not report list completeness. Review Fleetkeep before using fleet totals.',
  openTasks: maintenance.open.map(task => ({
    registration: task.registration ?? null,
    title: task.title,
    dueDate: task.dueDate ?? null,
    priority: task.priority,
  })),
  recentCompletedCount: maintenance.recent.length,
} }];
